INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('accessoire-aleatoire', 1, 'Accessoire aléatoire', 'Accessoire vierge de tout effet apparent ; son pouvoir ne se révèle qu’une fois porté, sauf pour un bijoutier capable d’en identifier la propriété.', 'monstres', 'Bestiaire 2.0 › ligne 28420');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('armure-funeraire', 2, 'Armure funéraire', 'Armure portée par les momies chargées de défendre les tombeaux ; il s’agit d’une armure intermédiaire que seuls les êtres liés à la magie de l’Espace/Temps peuvent revêtir.', 'monstres', 'Bestiaire 2.0 › ligne 28421');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('bandelette-de-momie', 3, 'Bandelette de momie', 'Bandelettes de lin imprégnées d’un parfum floral ancien ; en assembler six sur une armure complète lui confère +2 à l’initiative ainsi qu’une meilleure résistance à la fatigue.', 'monstres', 'Bestiaire 2.0 › ligne 28422');
