INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('os-metallique', 78, 'Os métallique', 'Os fusionné avec du métal ; un chaudronnier compétent peut le transformer en un matériau os et un lingot d’acier.', 'monstres', 'Bestiaire 2.0 › ligne 28497');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('os-moyen', 79, 'Os moyen', 'Os de taille intermédiaire ; 5 unités sont nécessaires pour produire un matériau os.', 'monstres', 'Bestiaire 2.0 › ligne 28498');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('os-vert', 80, 'Os vert', 'Os de couleur vert pâle imprégné de la magie du Vent ; une fois réduit en poudre, il devient un ingrédient utilisé dans l’alchimie rare et avancée.', 'monstres', 'Bestiaire 2.0 › ligne 28499');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('peau-de-carcalanche', 81, 'Peau de carcalanche', 'Peau gelée et résistante de ce zombi cristallisé, exploitable comme matériau léger pour la fabrication d’armures. Elle possède 1AP, 5AM et 1 de solidité par morceau.', 'monstres', 'Bestiaire 2.0 › ligne 28500');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('peau-du-radrak', 82, 'Peau du radrak', 'Peau épaisse du puissant radrak frénétique, utilisable pour fabriquer une armure conférant 5 AP, 7 AM et possédant 2 de solidité par morceau.', 'monstres', 'Bestiaire 2.0 › ligne 28501');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('peche', 83, 'Pêche', 'Fruit de l’Arcane, ingrédient alchimique utilisé dans des préparations en lien avec le chakra et la manipulation magique.', 'monstres', 'Bestiaire 2.0 › ligne 28502');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('petit-os', 84, 'Petit os', 'Fragment d’os commun ; 10 unités sont nécessaires pour produire un matériau os.', 'monstres', 'Bestiaire 2.0 › ligne 28503');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('plume-de-griffon', 85, 'Plume de griffon', 'Grande plume issue d’un griffon, utilisée en alchimie liée à la Foudre ainsi que dans la confection d’objets luxueux.', 'monstres', 'Bestiaire 2.0 › ligne 28504');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('plume-de-sang', 86, 'Plume de sang', 'Plume d’un aigle de sang, utilisée en alchimie liée au Sang ; sa teinte bordeaux est très recherchée.', 'monstres', 'Bestiaire 2.0 › ligne 28505');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('plume-tonnerre', 87, 'Plume tonnerre', 'Petite plume d’un pigeon foudroyant, utilisée en alchimie liée à la Foudre et dans la confection d’accessoires.', 'monstres', 'Bestiaire 2.0 › ligne 28506');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('poudre-dos-lumineuse', 90, 'Poudre d’os lumineuse', 'Résidus d’un lumiphage, cette poussière brillante est utilisée en alchimie.', 'monstres', 'Bestiaire 2.0 › ligne 28509');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('poussiere-de-cendre', 88, 'Poussière de cendre', 'Tas de cendres fines utilisé comme ingrédient en alchimie ou comme additif dans certaines pratiques de jardinage.', 'monstres', 'Bestiaire 2.0 › ligne 28507');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('poussiere-de-verre', 91, 'Poussière de verre', 'Poudre de verre extrêmement coupante et dangereuse à manipuler ; son véritable usage reste encore mal compris.', 'monstres', 'Bestiaire 2.0 › ligne 28510');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('poussiere-dos', 89, 'Poussière d’os', 'Résidu fin issu d’ossements broyés, ingrédient alchimique servant principalement à la fabrication d’huiles toxiques.', 'monstres', 'Bestiaire 2.0 › ligne 28508');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('prune', 92, 'Prune', 'Fruit de l’Eau, ingrédient alchimique associé aux préparations lié au chakra.', 'monstres', 'Bestiaire 2.0 › ligne 28511');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('raisin', 93, 'Raisin', 'Fruit de l’Ombre, ingrédient alchimique associé aux préparations mêlant santé et chakra.', 'monstres', 'Bestiaire 2.0 › ligne 28512');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('reglisse', 94, 'Réglisse', 'Fruit de la Corruption, ingrédient alchimique utilisé dans des mixtures altérant ou purifiant l’énergie corrompue.', 'monstres', 'Bestiaire 2.0 › ligne 28513');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sabre-de-cendre', 95, 'Sabre de cendre', 'Sabre formé de cendre compactée encore chaude, étonnamment rigide et particulièrement tranchant malgré son apparence fragile.', 'monstres', 'Bestiaire 2.0 › ligne 28514');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sabre-rouille', 96, 'Sabre rouillé', 'Arme détériorée dont la solidité est réduite d’un cran en raison de l’oxydation.', 'monstres', 'Bestiaire 2.0 › ligne 28515');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sel-dabysses', 97, 'Sel d’abysses', 'Grains bleus issus des restes d’un élémentaire de l’Eau, utilisés dans la fabrication d’huiles.', 'monstres', 'Bestiaire 2.0 › ligne 28516');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sel-de-chair', 98, 'Sel de chair', 'Grains rappelant du sel de couleur bordeaux, vestiges d’un élémentaire du Sang ; utilisés dans la fabrication d’huiles.', 'monstres', 'Bestiaire 2.0 › ligne 28517');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sel-de-givre', 99, 'Sel de givre', 'Grains cyan issus des restes d’un élémentaire de Glace, utilisés dans la fabrication d’huiles.', 'monstres', 'Bestiaire 2.0 › ligne 28518');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sel-de-rien', 100, 'Sel de rien', 'Grains blancs issus des restes d’un élémentaire du Vide, utilisés dans la fabrication d’huiles.', 'monstres', 'Bestiaire 2.0 › ligne 28519');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sel-de-roche', 101, 'Sel de roche', 'Grains bruns issus des restes d’un élémentaire de Terre, utilisés dans la fabrication d’huiles.', 'monstres', 'Bestiaire 2.0 › ligne 28520');
INSERT INTO monstre_butin_objet (id, rang, nom, texte, origine, source_ref) VALUES ('sel-de-tenebres', 102, 'Sel de ténèbres', 'Grains violets issus des restes d’un élémentaire de l’Ombre, utilisés dans la fabrication d’huiles.', 'monstres', 'Bestiaire 2.0 › ligne 28521');
